class RiskAssessment:
    def __init__(self, data):
        self.data = data

    def calculate_risk_score(self):
        # Assuming data is a DataFrame with 'impact' and 'likelihood' columns
        self.data['risk_score'] = self.data['impact'] * self.data['likelihood']
        return self.data

if __name__ == '__main__':
    data = pd.DataFrame({
        'impact': [5, 3, 4],
